import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, Loader2, Info } from 'lucide-react';
import { GeminiService } from '../services/geminiService';
import { ChatMessage } from '../types';

const ChatbotView: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { 
      role: 'model', 
      parts: [{ text: "Oi! Sou o EducaBot. 👋 Posso te ajudar a entender melhor como lidar com o diabetes no dia a dia. O que você quer saber hoje?" }] 
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const service = useRef(new GeminiService());

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput('');
    const newHistory: ChatMessage[] = [...messages, { role: 'user', parts: [{ text: userMsg }] }];
    setMessages(newHistory);
    setIsLoading(true);

    try {
      const response = await service.current.sendMessage(messages, userMsg);
      setMessages([...newHistory, { role: 'model', parts: [{ text: response || "Desculpe, tive um problema ao processar sua pergunta." }] }]);
    } catch (error) {
      console.error(error);
      setMessages([...newHistory, { role: 'model', parts: [{ text: "Opa, parece que minha conexão falhou. Tente novamente!" }] }]);
    } finally {
      setIsLoading(false);
    }
  };

  const suggestions = [
    "O que é o protocolo 15-15?",
    "Exemplos de 15g de carbo",
    "Por que meu açúcar sobe?",
    "Locais de aplicação"
  ];

  return (
    <div className="max-w-3xl mx-auto h-[70vh] flex flex-col animate-in fade-in zoom-in-95 duration-500">
      <div className="card-glass flex-1 rounded-[2rem] overflow-hidden flex flex-col relative border border-white/10">

        {/* Header */}
        <div className="bg-white/5 p-6 border-b border-white/10 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="gradient-primary p-2 rounded-xl text-white">
              <Bot size={24} />
            </div>
            <div>
              <h3 className="font-bold">EducaBot AI</h3>
              <div className="text-[10px] text-green-400 font-bold uppercase flex items-center gap-1">
                <span className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse" />
                Online
              </div>
            </div>
          </div>
          <div className="p-2 bg-white/5 rounded-full text-gray-500 hover:text-white cursor-help">
            <Info size={16} />
          </div>
        </div>

        {/* Chat Area */}
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6">
          {messages.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
                <div className={`shrink-0 w-8 h-8 rounded-lg flex items-center justify-center ${msg.role === 'user' ? 'bg-blue-500' : 'bg-purple-500'}`}>
                  {msg.role === 'user' ? <User size={16} /> : <Bot size={16} />}
                </div>
                <div className={`p-4 rounded-2xl text-sm leading-relaxed ${
                  msg.role === 'user' 
                    ? 'bg-blue-600 text-white rounded-tr-none' 
                    : 'bg-white/10 text-gray-200 rounded-tl-none border border-white/5'
                }`}>
                  {msg.parts[0].text}
                </div>
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-white/10 p-4 rounded-2xl flex items-center gap-3">
                <Loader2 className="animate-spin text-purple-400" size={18} />
                <span className="text-xs text-gray-500">Digitando...</span>
              </div>
            </div>
          )}
        </div>

        {/* Suggestions */}
        <div className="px-6 py-2 overflow-x-auto whitespace-nowrap scrollbar-hide flex gap-2">
          {suggestions.map((s, i) => (
            <button
              key={i}
              onClick={() => setInput(s)}
              className="px-3 py-1.5 bg-white/5 hover:bg-white/10 border border-white/10 rounded-full text-[10px] text-gray-400 transition-colors"
            >
              {s}
            </button>
          ))}
        </div>

        {/* Input */}
        <div className="p-6 bg-white/5 border-t border-white/10">
          <div className="relative">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Pergunte qualquer coisa..."
              className="w-full bg-deep-night border border-white/10 rounded-2xl py-4 pl-6 pr-14 text-sm focus:outline-none focus:border-purple-500/50 transition-colors"
            />
            <button
              onClick={handleSend}
              disabled={isLoading || !input.trim()}
              className="absolute right-2 top-2 bottom-2 aspect-square gradient-primary rounded-xl text-white flex items-center justify-center hover:scale-105 active:scale-95 transition-all disabled:opacity-50"
            >
              <Send size={18} />
            </button>
          </div>
          <p className="text-[9px] text-center text-gray-600 mt-4 uppercase font-bold tracking-widest">
            Atenção: O bot não prescreve doses e não substitui seu médico.
          </p>
        </div>
      </div>
    </div>
  );
};

export default ChatbotView;

