      <Navigation activeSection={activeSection} scrollToSection={scrollToSection} />

      <main className="relative z-10 w-full">
        {/* Seção Home */}
        <section id={Page.Home} className="reveal active min-h-screen flex items-center justify-center pt-20">
          <HomeView setPage={(page) => scrollToSection(page)} />
        </section>

        {/* Seção Fisiologia */}
        <section id={Page.Physiology} className="reveal py-24 lg:py-32">
          <PhysiologyView />
        </section>

        {/* Seção Insulina */}
        <section id={Page.Insulin} className="reveal py-24 lg:py-32">
          <InsulinView />
        </section>

        {/* Seção Carboidratos */}
        <section id={Page.Carbs} className="reveal py-24 lg:py-32">
          <CarbView />
        </section>

        {/* Seção S.O.S */}
        <section id={Page.SOS} className="reveal py-24 lg:py-32">
